(function() {
    'use strict';

    class MarketingWarRoomAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Digital Marketing War Room';
            this.version = '1.1.0';
            this.WEEKLY_BUDGET = 125000;
            this.CHANNEL_IDS = ['semInput', 'socialInput', 'emailInput', 'seoInput', 'influencerInput', 'displayInput'];
            this.ROUNDS = [
                {
                    week: 1,
                    titleKey: 'week1_title',
                    briefingKey: 'week1_briefing',
                    badgeKey: 'week1_badge',
                    crisisEvent: null,
                    productLaunch: false,
                    competitorAggression: 0.0,
                    marketModifier: 1.0
                },
                {
                    week: 2,
                    titleKey: 'week2_title',
                    briefingKey: 'week2_briefing',
                    badgeKey: 'week2_badge',
                    crisisEvent: 'sem_attack',
                    productLaunch: false,
                    competitorAggression: 0.6,
                    marketModifier: 0.92
                },
                {
                    week: 3,
                    titleKey: 'week3_title',
                    briefingKey: 'week3_briefing',
                    badgeKey: 'week3_badge',
                    crisisEvent: null,
                    productLaunch: true,
                    competitorAggression: 0.3,
                    marketModifier: 1.2
                },
                {
                    week: 4,
                    titleKey: 'week4_title',
                    briefingKey: 'week4_briefing',
                    badgeKey: 'week4_badge',
                    crisisEvent: null,
                    productLaunch: false,
                    competitorAggression: 0.2,
                    marketModifier: 1.1
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    totalRevenue: 0,
                    totalSpend: 0,
                    totalCustomers: 0,
                    brandAwareness: 30,
                    subscriberBase: 45000,
                    organicTraffic: 1000,
                    seoInvestmentQueue: [],
                    revenueHistory: [],
                    roasHistory: [],
                    awarenessHistory: [],
                    cacHistory: [],
                    conversionHistory: [],
                    weeklyRevenueHistory: [],
                    weeklySpendHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sem: 40000,
                    social: 30000,
                    email: 10000,
                    seo: 18000,
                    influencer: 15000,
                    display: 12000
                };
            }
            this._updateBriefing(state);
            this._setupBudgetTracker();
        }

        _setupBudgetTracker() {
            var self = this;
            this.CHANNEL_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() { self._updateBudgetDisplay(); });
                }
            });
            this._updateBudgetDisplay();
        }

        _updateBudgetDisplay() {
            var total = 0;
            this.CHANNEL_IDS.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) total += parseFloat(el.value) || 0;
            });
            var allocEl = document.getElementById('totalAllocated');
            var remainEl = document.getElementById('budgetRemaining');
            if (allocEl) allocEl.textContent = '$' + total.toLocaleString();
            if (remainEl) {
                var remaining = 125000 - total;
                remainEl.textContent = '$' + remaining.toLocaleString();
                remainEl.style.color = remaining < 0 ? '#e74c3c' : (remaining === 0 ? '#2ecc71' : '#f39c12');
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var badgeEl = document.getElementById('briefingBadge');
            if (titleEl && window.mySimulation) titleEl.textContent = window.mySimulation.t(round.titleKey);
            if (textEl && window.mySimulation) textEl.innerHTML = window.mySimulation.t(round.briefingKey);
            if (badgeEl && window.mySimulation) badgeEl.textContent = window.mySimulation.t(round.badgeKey);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var semEl = document.getElementById('semInput');
            var socialEl = document.getElementById('socialInput');
            var emailEl = document.getElementById('emailInput');
            var seoEl = document.getElementById('seoInput');
            var influencerEl = document.getElementById('influencerInput');
            var displayEl = document.getElementById('displayInput');

            if (semEl) decisions.sem = parseFloat(semEl.value) || 0;
            if (socialEl) decisions.social = parseFloat(socialEl.value) || 0;
            if (emailEl) decisions.email = parseFloat(emailEl.value) || 0;
            if (seoEl) decisions.seo = parseFloat(seoEl.value) || 0;
            if (influencerEl) decisions.influencer = parseFloat(influencerEl.value) || 0;
            if (displayEl) decisions.display = parseFloat(displayEl.value) || 0;

            var total = decisions.sem + decisions.social + decisions.email + decisions.seo + decisions.influencer + decisions.display;

            if (total < 1000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_too_low'), 'warning'
                );
                return false;
            }

            if (total > 126000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceeded'), 'warning'
                );
                return false;
            }

            var channels = [decisions.sem, decisions.social, decisions.email, decisions.seo, decisions.influencer, decisions.display];
            for (var i = 0; i < channels.length; i++) {
                if (channels[i] < 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('negative_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var week = state.currentPeriod;
            var roundIdx = Math.min(week - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var totalSpend = d.sem + d.social + d.email + d.seo + d.influencer + d.display;

            var semBase = 4.2;
            var socialBase = 2.8;
            var emailBase = 10.0;
            var seoImmediateBase = 0.4;
            var influencerBase = 2.3;
            var displayBase = 1.5;

            if (round.crisisEvent === 'sem_attack') {
                semBase *= 0.55;
            }
            semBase *= (1 - round.competitorAggression * 0.25);

            var diminish = function(spend, optimal) {
                if (spend <= 0) return 1.0;
                if (spend <= optimal) return 1.0;
                return (optimal / spend) * (1 + Math.log(spend / optimal) * 0.35);
            };

            semBase *= diminish(d.sem, 47000);
            socialBase *= diminish(d.social, 37000);
            emailBase *= diminish(d.email, 12000);
            influencerBase *= diminish(d.influencer, 20000);
            displayBase *= diminish(d.display, 15000);

            var trafficRatio = (d.sem + d.social) / Math.max(totalSpend, 1);
            displayBase *= (1 + trafficRatio * 0.45);

            socialBase *= (1 + ds.brandAwareness / 250);

            var emailCeiling = ds.subscriberBase * 0.18;
            var effectiveEmailSpend = Math.min(d.email, emailCeiling);

            ds.seoInvestmentQueue.push(d.seo);
            var laggedSeoRevenue = 0;
            if (ds.seoInvestmentQueue.length >= 3) {
                laggedSeoRevenue = ds.seoInvestmentQueue[ds.seoInvestmentQueue.length - 3] * 2.8;
            }
            var immediateSeoRevenue = d.seo * seoImmediateBase;

            ds.organicTraffic += d.seo * 0.04;

            var launchMult = 1.0;
            if (round.productLaunch) {
                launchMult = 1.35;
                influencerBase *= 1.4;
                emailBase *= 1.3;
                semBase *= 1.15;
            }

            var mktMod = round.marketModifier;

            var semRevenue = Math.max(0, d.sem * semBase * mktMod * launchMult);
            var socialRevenue = Math.max(0, d.social * socialBase * mktMod * launchMult);
            var emailRevenue = Math.max(0, effectiveEmailSpend * emailBase * mktMod * launchMult);
            var seoRevenue = Math.max(0, (immediateSeoRevenue + laggedSeoRevenue) * mktMod * launchMult);
            var influencerRevenue = Math.max(0, d.influencer * influencerBase * mktMod * launchMult);
            var displayRevenue = Math.max(0, d.display * displayBase * mktMod * launchMult);

            var rawTotal = semRevenue + socialRevenue + emailRevenue + seoRevenue + influencerRevenue + displayRevenue;

            var noise = 0.92 + Math.random() * 0.16;
            var weeklyRevenue = Math.round(rawTotal * noise);

            var blendedROAS = totalSpend > 0 ? weeklyRevenue / totalSpend : 0;
            blendedROAS = Math.round(blendedROAS * 100) / 100;

            var aov = 80;
            var newCustomers = Math.round(weeklyRevenue / (aov * 1.6));
            var weeklyCAC = newCustomers > 0 ? Math.round(totalSpend / newCustomers) : 0;

            var awarenessGain = (d.social * 0.00018 + d.influencer * 0.00028 + d.display * 0.00012 + d.seo * 0.00008) * mktMod;
            var awarenessDecay = ds.brandAwareness * 0.04;
            ds.brandAwareness = Math.min(100, Math.max(0, ds.brandAwareness + awarenessGain - awarenessDecay));
            ds.brandAwareness = Math.round(ds.brandAwareness * 10) / 10;

            var newSubs = Math.round((d.social * 0.02 + d.seo * 0.015 + d.influencer * 0.025 + d.display * 0.008) * mktMod);
            ds.subscriberBase += newSubs;

            var baseConv = 2.8;
            var convBoost = 0;
            if (d.email > 5000) convBoost += 0.3;
            if (d.sem > 20000) convBoost += 0.2;
            if (ds.brandAwareness > 40) convBoost += 0.35;
            if (round.productLaunch) convBoost += 0.5;
            var conversionRate = Math.min(6.5, baseConv + convBoost);
            conversionRate = Math.round(conversionRate * 10) / 10;

            ds.totalRevenue += weeklyRevenue;
            ds.totalSpend += totalSpend;
            ds.totalCustomers += newCustomers;

            ds.revenueHistory.push(weeklyRevenue);
            ds.weeklyRevenueHistory.push(weeklyRevenue);
            ds.weeklySpendHistory.push(totalSpend);
            ds.roasHistory.push(blendedROAS);
            ds.awarenessHistory.push(ds.brandAwareness);
            ds.cacHistory.push(weeklyCAC);
            ds.conversionHistory.push(conversionRate);

            var self = this;
            var gradedPeriod = state.currentPeriod;
            if (gradedPeriod < this.ROUNDS.length) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: gradedPeriod + 1 });
                }, 500);
            }

            return {
                period: state.currentPeriod,
                revenue: weeklyRevenue,
                spend: totalSpend,
                roas: blendedROAS,
                newCustomers: newCustomers,
                cac: weeklyCAC,
                brandAwareness: ds.brandAwareness,
                conversionRate: conversionRate,
                totalRevenue: ds.totalRevenue,
                totalCustomers: ds.totalCustomers
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('roasDisplay', 'domainState.totalRevenue',
                function(v) {
                    var s = window.mySimulation && window.mySimulation.state;
                    if (s && s.domainState && s.domainState.totalSpend > 0) {
                        return (Math.round(s.domainState.totalRevenue / s.domainState.totalSpend * 100) / 100) + 'x';
                    }
                    return '0x';
                });
            uiManager.bind('cacDisplay', 'domainState.totalCustomers',
                function(v) {
                    var s = window.mySimulation && window.mySimulation.state;
                    if (s && s.domainState && v > 0) {
                        return '$' + Math.round(s.domainState.totalSpend / v);
                    }
                    return '$0';
                });
            uiManager.bind('awarenessDisplay', 'domainState.brandAwareness',
                function(v) { return Math.round(v * 10) / 10; });
            uiManager.bind('conversionDisplay', 'results.conversionRate',
                function(v) { return (v || 2.8) + '%'; });
            uiManager.bind('customersDisplay', 'domainState.totalCustomers',
                function(v) { return Math.round(v).toLocaleString(); });
        }

        getChartConfig() {
            return {
                revenueChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Weekly Revenue ($)',
                            data: [],
                            backgroundColor: 'rgba(46, 204, 113, 0.6)',
                            borderColor: '#2ecc71',
                            borderWidth: 2,
                            borderRadius: 6
                        }, {
                            label: 'Weekly Spend ($)',
                            data: [],
                            backgroundColor: 'rgba(231, 76, 60, 0.4)',
                            borderColor: '#e74c3c',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Revenue vs Spend', color: '#b0b0cc' },
                            legend: { labels: { color: '#b0b0cc' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#8888aa' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#8888aa' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                },
                kpiChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'ROAS (x)',
                            data: [],
                            borderColor: '#3498db',
                            backgroundColor: 'rgba(52,152,219,0.1)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3,
                            yAxisID: 'y'
                        }, {
                            label: 'Brand Awareness',
                            data: [],
                            borderColor: '#9b59b6',
                            backgroundColor: 'rgba(155,89,182,0.1)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Key Performance Indicators', color: '#b0b0cc' },
                            legend: { labels: { color: '#b0b0cc' } }
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                display: true,
                                position: 'left',
                                beginAtZero: true,
                                title: { display: true, text: 'ROAS', color: '#8888aa' },
                                ticks: { color: '#8888aa' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            },
                            y1: {
                                type: 'linear',
                                display: true,
                                position: 'right',
                                min: 0,
                                max: 100,
                                title: { display: true, text: 'Awareness Index', color: '#8888aa' },
                                ticks: { color: '#8888aa' },
                                grid: { drawOnChartArea: false }
                            },
