        getHint(state, results) {
            if (!results) return null;
            if (results.roas < 2.5) return window.mySimulation.t('hint_low_roas');
            if (state.domainState.brandAwareness < 28) return window.mySimulation.t('hint_low_awareness');
            if (results.cac > 120) return window.mySimulation.t('hint_high_cac');

            var emailPct = (state.decisions.email || 0) / this.WEEKLY_BUDGET;
            if (emailPct < 0.04) return window.mySimulation.t('hint_email_neglect');

            var seoPct = (state.decisions.seo || 0) / this.WEEKLY_BUDGET;
            if (seoPct < 0.06) return window.mySimulation.t('hint_seo_neglect');

            if (results.roas >= 4.0 && state.domainState.brandAwareness >= 40) return window.mySimulation.t('hint_great_balance');

            return null;
        }

