        getPerformanceSummary(history) {
            if (!history.length) return {};

            var totalRevenue = 0;
            var totalSpend = 0;
            var totalCustomers = 0;
            var finalAwareness = 30;
            var convSum = 0;

            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalRevenue += r.revenue || 0;
                totalSpend += r.spend || 0;
                totalCustomers += r.newCustomers || 0;
                finalAwareness = r.brandAwareness || finalAwareness;
                convSum += r.conversionRate || 0;
            }

            var blendedROAS = totalSpend > 0 ? Math.round(totalRevenue / totalSpend * 100) / 100 : 0;
            var avgCAC = totalCustomers > 0 ? Math.round(totalSpend / totalCustomers) : 0;
            var avgConv = history.length > 0 ? Math.round(convSum / history.length * 10) / 10 : 0;

            var score = 0;

            if (totalRevenue >= 2100000) score += 20;
            else if (totalRevenue >= 1800000) score += 16;
            else if (totalRevenue >= 1400000) score += 10;
            else score += 4;

            if (blendedROAS >= 5.5) score += 25;
            else if (blendedROAS >= 3.5) score += 20;
            else if (blendedROAS >= 2.5) score += 12;
            else score += 5;

            if (avgCAC <= 65) score += 15;
            else if (avgCAC <= 95) score += 12;
            else if (avgCAC <= 130) score += 7;
            else score += 3;

            if (finalAwareness >= 50) score += 15;
            else if (finalAwareness >= 38) score += 12;
            else if (finalAwareness >= 32) score += 7;
            else score += 3;

            if (avgConv >= 4.0) score += 10;
            else if (avgConv >= 2.5) score += 8;
            else if (avgConv >= 1.8) score += 4;
            else score += 2;

            if (totalCustomers >= 9500) score += 15;
            else if (totalCustomers >= 6500) score += 12;
            else if (totalCustomers >= 4000) score += 7;
            else score += 3;

            var t = function(k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; };

            var performance = t('tier_needs_improvement');
            if (score >= 85) performance = t('tier_excellent');
            else if (score >= 70) performance = t('tier_strong');
            else if (score >= 55) performance = t('tier_competent');

            var insights = [];
            if (blendedROAS < 3.5) insights.push(t('insight_low_roas'));
            if (finalAwareness < 38) insights.push(t('insight_low_awareness'));
            if (avgCAC > 95) insights.push(t('insight_high_cac'));
            if (totalRevenue < 1800000) insights.push(t('insight_low_revenue'));
            if (blendedROAS >= 5.0 && finalAwareness >= 45) insights.push(t('insight_outstanding'));
            if (insights.length === 0) insights.push(t('insight_solid'));

            return {
                totalRevenue: totalRevenue,
                blendedROAS: blendedROAS,
                totalCustomers: totalCustomers,
                avgCAC: avgCAC,
                finalAwareness: Math.round(finalAwareness),
                avgConversion: avgConv,
                score: score,
                performance: performance,
                insights: insights
            };
        }

